import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';
import {hashBytes,importPackage} from '../src/package';import {ensurePianoReady} from '../src/piano-readiness';
import {preparationRequestIdentity} from '../src/piano-preparation-identity';import {pianoRequestAuthority} from '../src/piano-request-authority';
// Generated by exact accepted Viewer 94ef94b + retained ISO da93cf9, not by
// the identity implementation under test. Musical data is newly authored.
const bytes=new Uint8Array(readFileSync(new URL('../fixtures/authored-preparation-v1.isoscore',import.meta.url)));
test('an independently frozen v1 edition cold-reads exact bytes while new requests use versioned new-engine identity',async()=>{
 assert.equal(await hashBytes(bytes),'5c94ab9d3eb78f2109b04129fc065c220705f611137f3f1a7325dffb1012f52f');
 const p=await importPackage(bytes);assert.equal(p.preparationIdentity!.version,'viewer-piano-preparation-v1');
 assert.equal(p.preparationIdentity!.sha256,'2f4bc1a0f1ecd44ea66ce497434cd3b9f2e9e83fce4e102639f936a9c22cba01');
 const retained=await ensurePianoReady({packageBytes:bytes,layout:'janko-four-row',intent:'read-retained'});
 assert.equal(retained.status,'editable','message' in retained?retained.message:undefined);assert.deepEqual(retained.packageBytes,bytes);
 const constraints=pianoRequestAuthority(p,p.sourceScore!,'janko-four-row',p.fingerLayer,undefined,'retain-imported');
 assert.notEqual(await preparationRequestIdentity(p,'retain-imported',constraints),p.preparationIdentity!.requestSha256);
 const fresh=await ensurePianoReady({packageBytes:bytes,layout:'janko-four-row',performingHandPolicy:'retain-imported'});
 assert.equal(fresh.status,'editable','message' in fresh?fresh.message:undefined);if(fresh.status!=='editable')return;
 assert.equal(fresh.package.preparationIdentity!.version,'viewer-piano-preparation-v2');assert.notDeepEqual(fresh.packageBytes,bytes);
 assert.deepEqual(fresh.package.pages,p.pages);assert.deepEqual(fresh.package.files['source-score.json'],p.files['source-score.json']);
});
